import{_ as r,l as t,o as e,c as n,v as o,p as s,x as i,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"轮询 I/O","description":"","frontmatter":{"title":"轮询 I/O","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/io-polling.md","filePath":"cs/io-polling.md","lastUpdated":1789023840000}'),E={name:"cs/io-polling.md"};function h(_,a,u,m,I,P){const l=t("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="轮询-i-o" tabindex="-1">轮询 I/O <a class="header-anchor" href="#轮询-i-o" aria-label="Permalink to &quot;轮询 I/O&quot;">​</a></h1><div class="epigraph"><p>当完成已在微秒级，进中断再调度的税可能大于等一轮门铃；轮询让提交线程自己收 CQ。</p><footer>—— 据 Linux blk-mq poll / io_uring IOPOLL 文档；NVMe 规范对完成队列的说明</footer></div><p><a href="/cs/dax-pmem">上一课</a>甚至没有完成队列。<a href="/cs/nvme-driver">NVMe</a> 默认 MSI-X：延迟 = 设备 + 中断 + 软中断 + 唤醒。<a href="/cs/posix-aio">POSIX AIO</a> 没解决这条。缺口是 <strong>轮询 I/O</strong>：谁在转、何时混合中断。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>高 IOPS 时中断风暴。<code>nvme poll</code> 或 io_uring <code>IORING_SETUP_IOPOLL</code>：提交后在 CQ 上转，直到完成或让出。缺口：要独占 CPU；低负载浪费能源；与 <a href="/cs/blk-schedulers">blk 调度</a> 的 none 常一起用；缓冲 I/O 难以 poll（完成路径在缓存）。本课对象是块层/uring 轮询，不是网卡 NAPI——NAPI 在网络课。</p><p><span class="marginnote">hipri 轮询队列、混合模式（超时才中断）是工程旋钮。教学上：完成通知从 IRQ 换成 busy-wait。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用提交 uring SQE（DIRECT 文件或 nvme），内核把命令进 SQ，线程在 <code>io_cqring</code> 或驱动 <code>poll</code> 钩上转。对照中断路径：无 <code>irq_handler</code>、少一次调度。对照 DAX：根本无 CQ。对照 SCSI：HBA 是否支持轮询因卡而异。</p>',8)),(e(),s(c,null,{default:i(()=>[p(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E6%8F%90%E4%BA%A4%E5%91%BD%E4%BB%A4%22%5D%20--%3E%20SQ%5B%22NVMe%20SQ%22%5D%0A%20%20SQ%20--%3E%20CQ%5B%22CQ%20%E5%8F%AF%E8%83%BD%E5%B7%B2%E6%9C%89%E5%AE%8C%E6%88%90%22%5D%0A%20%20IRQ%5B%22%E4%B8%AD%E6%96%AD%E8%B7%AF%E5%BE%84%22%5D%20-.-%3E%7C%22%E8%B7%B3%E8%BF%87%22%7C%20POLL%5B%22%E7%BA%BF%E7%A8%8B%E8%BD%AE%E8%AF%A2%20CQ%22%5D%0A%20%20POLL%20--%3E%20APP%5B%22%E7%94%A8%E6%88%B7%E6%94%B6%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>轮询把尾延迟的软件部分压下去，用 CPU 换 IRQ。这是存储栈与后课网络旁路的共同主题。不要写成实时 FIFO 保证：轮询线程仍可能被抢占，除非隔核与 PREEMPT_RT 后课。能源：空转 C-state 进不去，<a href="/cs/cpuidle-cstate">cpuidle</a> 会再出现。</p><p>安全：用户轮询不授予绕过权限检查；只是完成路径。</p><p>实现上：hipri 轮询需要队列支持，且通常要求 O_DIRECT。线程被调度跑开则轮询变成「忙等别人的完成」，要绑核。混合模式在超时后降回中断，避免空转。 读法上只引用<a href="/cs/dax-pmem">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>轮询 I/O</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 io_uring 全部 opcode 写成手册。不保证虚拟机里轮询有效（要半虚拟 poll 队列）。下一课用 cgroup 限制这块带宽：blkio。</p><p>版本字段会变，课序钉的是机制对象「轮询 I/O」，不是某一主线内核的结构体名。 后课默认：完成可以靠轮询收取。按组限制 IOPS/带宽，下一课 blkio cgroup。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>轮询用 CPU 收 CQ，去掉中断唤醒。</li><li>适合 DIRECT 高 IOPS；低负载不合适。</li><li>blkio 限制是下一课。</li><li>出处：Linux io_uring IOPOLL；NVMe；blk-mq poll。</li></ul>',11))])}const C=r(E,[["render",h]]);export{B as __pageData,C as default};
